; 0xF30800-0xF3080F -- 16 bytes copied to RAM 0x5200 at init
;   prom_a `ld BC,0x0010 / ld XIY,0x00F30800 / ld XIX,0x00005200 / ldir`.
;   The four blocks tile 0xF30800-0xF3167F exactly
;   (0x10 + 0x650 + 0x650 + 0x1D0 = 0xE80), which is what says this
;   part of the range is NOT display lists.
; ------------------------------------------------------------------
RamDefault_F30800:
	.byte 0x10, 0x00, 0x00, 0x00, 0x60, 0x06, 0x00, 0x00, 0xB0, 0x0C, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 ; F30800  ....`...........

; ------------------------------------------------------------------
; 0xF30810-0xF30E5F -- 1616 bytes copied to RAM 0x5210 at init
;   prom_a `ld BC,0x0650 / ld XIY,0x00F30810 / ld XIX,0x00005210 / ldir`.
;   The four blocks tile 0xF30800-0xF3167F exactly
;   (0x10 + 0x650 + 0x650 + 0x1D0 = 0xE80), which is what says this
;   part of the range is NOT display lists.
